function summarizeWindow(events, nowMs, windowMs, cap) {
  const seenIds = new Set();
  const qualifying = [];
  const list = Array.isArray(events) ? events : [];

  for (const ev of list) {
    if (ev === null || typeof ev !== 'object') continue;

    const id = typeof ev.id === 'string' ? ev.id : '';
    if (id !== '') {
      if (seenIds.has(id)) continue;
      seenIds.add(id);
    }

    if (typeof ev.ts !== 'number' || !Number.isFinite(ev.ts)) continue;
    if (ev.ts < nowMs - windowMs || ev.ts > nowMs) continue;
    if (ev.provider !== 'opencode-go') continue;
    if (ev.error) continue;
    if (typeof ev.model !== 'string') continue;
    if (ev.model.toLowerCase().endsWith('-free')) continue;

    qualifying.push(ev);
  }

  const used = qualifying.length;
  let minTs = null;
  const counts = Object.create(null);

  for (const ev of qualifying) {
    if (minTs === null || ev.ts < minTs) minTs = ev.ts;

    let model = ev.model;
    const lower = model.toLowerCase();
    const prefix = 'opencode-go/';
    if (lower.startsWith(prefix)) {
      model = model.slice(prefix.length);
    }
    const key = model.toLowerCase();
    counts[key] = (counts[key] || 0) + 1;
  }

  const byModel = {};
  for (const key of Object.keys(counts).sort()) {
    byModel[key] = counts[key];
  }

  let oldestExpiresAt = null;
  if (used > 0) {
    oldestExpiresAt = minTs + windowMs;
  }

  return {
    used: used,
    remaining: Math.max(0, cap - used),
    pct: Math.round((used / cap) * 1000) / 10,
    overCap: used > cap,
    oldestExpiresAt: oldestExpiresAt,
    byModel: byModel,
  };
}
